  PanelText_UI_Events_2ndAnnivWB_StageGroup_Text_C_Introduction_Content = {
    Text = "มาเถอะ ด้วยความบ้าคลั่ง การฆ่า และความเจ็บปวดเป็นโน้ต จงบรรเลงเพลงสวดอุทิศที่ส่องสว่างระหว่างดาวเคราะห์ \n สิ่งมีชีวิตสูงสุดที่โง่เขลาในความโกลาหลนี้ ไม่ควรตื่นขึ้น ไม่ว่าจะเป็นในขณะนี้ หรือในอนาคต."
