  PanelText_UI_Events_Activity_StageGroup_Text_C_Introduction_Content = {
    Text = "สิ่งที่พระเจ้าได้สัญญา กำลังจะมาถึง.\nการรอคอยนับพันปีกำลังจะนำมาซึ่งจุดสิ้นสุดแห่งความยินดี,      ที่ดินที่ได้รับคำสัญญาจากท้องทะเลจะขึ้นมา.\nพระเจ้าจะฟื้นคืนชีวิตจากอกของพระเจ้าแม่,      เมื่อถึงวันที่เจ็ด,      โลกใบใหม่จะมาถึง."
