  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "ไฟสปอตไลท์สว่างขึ้น เสียงปรบมือเงียบลง ผู้ชมกำลังรอคอย\nถึงเวลาขึ้นเวทีแล้ว ลูกรักของฉัน จงก้าวขึ้นไป แสดง ฉีกทึ้งหัวใจของพวกเจ้าออกมา และขายความลับที่ซ่อนลึกที่สุด จงนำบาดแผลอันเจ็บปวดที่สุดของพวกเจ้ามาทำเป็นขนมหวานเพื่อความบันเทิงของผู้คน จงดื่มด่ำกับแสงไฟบนเวทีที่ส่องสว่างเพื่อเจ้าเพียงผู้เดียวอย่างโลภเลิศ จนกว่าม่านจะฝังเจ้าและผู้ชมไว้ด้วยกัน\nนี่คือเวทีที่ถูกลิขิตไว้สำหรับพวกเจ้า จงก้าวขึ้นไปเถิด! อย่ากลัว ไม่ต้องประหม่า"
