  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nใต้เชิงเขาหิมะ ไกด์ทุกคนจดจำ และเด็กทุกคนร้องเพลงถ่ายทอดกัน. นั่นคือ化身แห่งเจตจำนงของเทือกเขาหิมะอันสูงตระหง่าน นั่นคือเทพธิดาผู้เมตตา อุมาปติ.\nพลังศักดิ์สิทธิ์ของพระนางกระจัดกระจายสู่โลกมนุษย์ สมบัติของพระนางหาไม่พบ ใกล้แค่เอื้อมแต่กลับสูญหายไร้ร่องรอย. จงละทิ้งบางสิ่ง จงยึดมั่นในบางสิ่ง.\nผู้ใดที่ไม่บริสุทธิ์ใจต่อตัวตนที่แท้จริงของเทพธิดา จะถูกฝังอยู่ในเทือกเขาหิมะชั่วนิรันดร์ พร้อมกับเทือกเขาหิมะที่ดับสูญ."
  },
