  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "ชีวิตของนกบินนั้นถูกกำหนดให้เป็นชีวิตที่เป็นอิสระ คุณควรเห็นมันในขณะที่มันฟักออกจากไข่ มันได้แย่งชิงอิสระในการมีชีวิตจากมือแห่งความตาย คุณควรเห็นมันในขณะที่มันเรียนรู้การบิน มันได้แย่งชิงอิสระในการมีชีวิตอยู่คนเดียวจากรังอันอบอุ่นในความสะดวกสบาย หากวันนี้คุณโยนกุญแจแห่งอิสระลงไปในความลึกแห่งความตาย มันจะไม่ลังเลที่จะกระโดดลงไปในความตาย โดยเลือกที่จะเผชิญหน้ากับพายุแห่งความตายในชีวิตที่แคบและอิสระที่ไม่มีที่สิ้นสุด。"
