  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "ในเมืองเล็กๆ ริมทะเลแห่งนี้ มีถนนการค้าที่เจริญรุ่งเรือง การค้าทางทะเลทำให้ที่นี่มีสินค้าทันสมัยมากมายเพียงจ่ายเงินเลโอฟังเพียงพอ คุณก็จะได้รับสินค้าที่น่าพอใจ\nยกเว้นร้านเล็กๆ ที่มุมถนนนั้น เป็นร้านเล็กๆ ที่เต็มไปด้วยของโบราณที่น่าทึ่ง ในควันจากการสูบpipe เจ้าของร้านที่สวมหมวกปีกกว้างจะค่อยๆ ยิ้มให้คุณ\n“ยินดีต้อนรับสู่ร้านค้าปลดทุกข์ ที่นี่สามารถตอบสนองความต้องการของคุณได้ทุกอย่าง เพียงจ่ายค่าตอบแทนที่เหมาะสม...”\n“แน่นอน แน่นอน ราคายุติธรรม ไม่มีการหลอกลวงผู้สูงอายุและเด็ก”"
