  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "เธอยืนอยู่บนโลกาอีกครั้ง การล้างแค้นที่เผาทุกสิ่งกำลังมาถึงตามนัด \n\n นั่นคือการล่าที่ไม่มีวันหยุดพัก นั่นคือเปลวเพลิงที่ร้อนแรงของผู้ครอบครองเปลวเพลิงระเบิด \n\n เธอจะเดินผ่านทุกมุม ทุกซอก ทุกมุมมืด และฆ่าฟันทุกคนที่ทำสัญญากับยมทูต \n\n หนีไปเถอะ หนีไปเถอะ หนีไปยังความมืดที่ลึกยิ่งขึ้น หนีไปยังที่ที่คิดว่าตนเองจะไม่ถูกพบ \n\n แม้ว่านี่จะไม่มีความหมาย เพราะพระองค์จะเหยียบย่ำผ่านทุกโลก \n\n พระองค์จะล่าทุกคน จนกว่าทุกสิ่งจะถูกเผาเป็นเถ้าถ่าน。"
  },
