    Text = "ท้องฟ้า~แจ่มใส~ทะเล~สงบ~\nมอส~เพื่อน~ลูกถ่านขนาดเล็ก~ออกเดินทาง!\nพายุไม่กลัว ฟ้าผ่าไม่กลัว มอส เพื่อน ลูกถ่านขนาดเล็ก~\nเพื่อเสรีภาพ ต้อง·ออก·เดินทาง"
