  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "วันหนึ่งทันใด คุณพบว่าตัวเองเปลี่ยนไปแล้ว\nไม่มีใครสังเกตเห็นเรื่องนี้ เพราะคุณมีพฤติกรรมและท่าทางเหมือนเดิม หน้าตาก็ยังงดงามเหมือนเดิม\nแต่คุณรู้ดี ว่าหัวใจที่เคยสดใสแดงแจ๋ ตอนนี้ถูกปกคลุมด้วยหน้ากากที่ทำจากไอหมอก\n「ถ้าฉันสามารถปลอมตัวไปเรื่อยๆ แบบนี้ได้ ฉันยังคงเป็นตัวฉันคนเดิมอยู่หรือเปล่า?」\nยินดีด้วย คำถามนี้ไม่ได้อยู่ในสมองของคุณนานเกินหนึ่งวินาที เพราะก่อนที่จะเปิดเผยหน้ากากนั้น ไม่มีใครรู้ความคิดที่แท้จริงของคุณ\n「งั้นก็ออกเดินทางกันเถอะ~」"
