  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "ระหว่างเหตุผลกับความคราช ภาพวาดกลอุบายค่อยๆ แผ่ขยายออกไป \nภาพหลอนที่คุณดูถูกสร้างสรรค์สีสันอันงดงาม \nการควบคุมที่คุณหวาดกลัวกลายเป็นรูปแบบของความภักดี \nที่นี่ ความบ้าคลั่งคือสัญชาตญาณของศิลปะ เป็นรากฐานของโลก \nคือความจริงเดียวที่ไม่เคยโกหก。"
