    Text = "วิทยาศาสตร์ ไม่สำคัญ\nจริยธรรม ไม่สำคัญ\nศีลธรรม ไม่สำคัญ\nชีวิต ความตาย ความหวัง ความสิ้นหวัง... ท้ายที่สุดของท้ายที่สุด บนสมุดบันทึกในห้องใต้ดิน ลายมือสองแบบทิ้งข้อสรุปเดียวกันไว้\nพระองค์ทั้งหลายกล่าวว่า: 「ดูสิ ความรักคือธีมเดียวที่เป็นนิรันดร์」"
