  PanelText_UI_Events_Panel_Sorel_StageGroup_Text_C_Introduction_Content = {
    Text = "หลายปีต่อมา นักเขียนชีวประวัติได้เคาะประตูบ้านของเธอในยามเย็น\nวันนั้นพวกเธอได้พูดคุยกันมากมาย ตั้งแต่หินอาเกตไปจนถึงคฤหาสน์ที่ดอกกุหลาบร่วงโรย...\nตอนนี้ นักเขียนได้รวบรวมคำพูดเล็กน้อยเหล่านี้มาเขียนเป็นหนังสือ เพื่อมอบให้กับทุกท่านที่นั่งอยู่ที่นี่。"
